test('two first-load demo tabs share one seed receipt and sync their own committed turn',async({page,context},info)=>{
 const other=await context.newPage();listen(other);try{await Promise.all([clock(page),clock(other)]);await Promise.all([page.goto('./?demo=battle-sword'),other.goto('./?demo=battle-sword')]);for(const tab of[page,other]){await settledControlOrFailedRead(tab);await expect(tab.getByTestId('demo-persistent-label')).toBeVisible();await expect.poll(()=>demoGame(tab)).not.toBeNull();await expect(tab.getByTestId('save-status')).not.toContainText('保存中');if(await tab.getByTestId('save-status').textContent()==='本次未保存'){await expect(tab.getByTestId('error')).toBeVisible();await tab.reload();await expect(tab.getByTestId('save-status')).toHaveText('已保存');}}const before=await demoGame(page);expect(await demoGame(other)).toEqual(before);const db=(await demoDatabase(page))!;expect((await raw(page,db))['full-receipts'].keys).toHaveLength(1);const after=await cycle(page,info,'shared-demo-turn',3000,()=>page.getByTestId('attack').click());await expect.poll(async()=>(await demoGame(other))?.core.revision).toBe(1);await expect.poll(()=>other.getByTestId('save-status').textContent()).toBe('已保存');expect(await demoGame(other)).toEqual(after);const receipts=(await raw(page,db))['full-receipts'];expect(receipts.values.filter((r:any)=>r.format==='chenyuan-control-receipt')).toHaveLength(1);expect(receipts.values.filter((r:any)=>r.format==='chenyuan-receipt')).toHaveLength(1);expect(receipts.values.filter((r:any)=>r.format==='chenyuan-activity-receipt')).toHaveLength(1);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);await evidence(info,'shared-seed-and-cycle',{before,after,receipts});}finally{expect(pageErrors.get(other)??[]).toEqual([]);await other.close();}
});
async function settledControlOrFailedRead(page:Page){await expect.poll(async()=>await page.getByTestId('action-execution').isVisible()?'control':await page.getByTestId('save-status').textContent()==='已保存'?'read':'waiting').not.toBe('waiting');if(await page.getByTestId('action-execution').isVisible()){await page.clock.runFor(600);await expect(page.getByTestId('save-status')).not.toHaveText('行动中');await expect(page.getByTestId('save-status')).not.toHaveText('保存中');}}
